'use strict';
const $=s=>document.querySelector(s);
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let tracks=[],events=[],selected=null,selectedDetail=null,localAudioUrl=null;
const audio=$('#audio');
function releaseAudio(){audio.pause();audio.removeAttribute('src');audio.load();if(localAudioUrl){URL.revokeObjectURL(localAudioUrl);localAudioUrl=null;}$('#audio-file').value='';}
function selectTrack(t){if(selected?.id!==t.id){releaseAudio();selected=t;audio.hidden=!t.audioSrc;$('#audio-status').textContent=t.audioSrc?'登録音源':'音源未登録 · 手元の音源で試せます';if(t.audioSrc)audio.src=t.audioSrc;}$('#playing-title').textContent=t.title;$('#player').hidden=false;document.body.classList.add('has-player');}
function setPanel(panel){if(panel==='lyrics'&&!selectedDetail?.lyricsByOwner)return;$('#notes-panel').hidden=panel!=='notes';$('#lyrics-panel').hidden=panel!=='lyrics';document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.panel===panel)));}
function openDetail(t){selectedDetail=t;$('#detail-period').textContent=t.displayPeriod;$('#detail-title').textContent=t.title;$('#credits').textContent='作曲：'+t.composer+(t.lyricist?' ／ 作詞：'+t.lyricist:' ／ 作詞：未確認')+(t.audioVersionYear?' ／ 音源制作：'+t.audioVersionYear:'');$('#notes-then').textContent=t.notesThen||'曲ごとのノーツは、これから。時代の背景は履歴の「時代のノーツ」で読めます。';$('#notes-now').textContent=t.notesNow||'現在の音源や、今聴いて感じることを追記します。';$('#detail-source').hidden=!t.sourceUrl;if(t.sourceUrl)$('#detail-source').href=t.sourceUrl;$('#lyric-status').textContent=t.lyricCreditStatus==='unconfirmed'?'作詞者は未確認です。本人作詞と確認できた曲だけ歌詞を掲載します。':'作詞：'+t.lyricist+'。本人が作詞していない曲の歌詞は掲載しません。';$('[data-panel="lyrics"]').hidden=!t.lyricsByOwner||!t.lyrics;$('#lyrics').textContent=t.lyricsByOwner?(t.lyrics||''):'';setPanel('notes');$('#detail').showModal();}
$('#detail-play').addEventListener('click',()=>{selectTrack(selectedDetail);$('#detail').close();$('#audio-file').focus();});
$('#close-detail').addEventListener('click',()=>$('#detail').close());
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close();}});
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
$('#close-player').addEventListener('click',()=>{releaseAudio();selected=null;$('#player').hidden=true;document.body.classList.remove('has-player');});
$('#audio-file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('audio/')){$('#audio-status').textContent='音声ファイルを選んでください';return;}audio.pause();if(localAudioUrl)URL.revokeObjectURL(localAudioUrl);localAudioUrl=URL.createObjectURL(f);audio.src=localAudioUrl;audio.hidden=false;$('#audio-status').textContent='端末内の試聴：'+f.name;});
audio.addEventListener('error',()=>{$('#audio-status').textContent='この音源を再生できません。別の形式をお試しください。';});
window.addEventListener('pagehide',()=>{if(localAudioUrl)URL.revokeObjectURL(localAudioUrl);});
const branchFor=e=>e.id.startsWith('felice')?'felice':e.id==='patalp'?'patalp':'main';
function render(){const list=$('#history-list');list.replaceChildren();$('#count').textContent=tracks.length+' SONGS';for(const e of events){const li=el('li');li.dataset.event=e.id;li.dataset.branch=branchFor(e);const head=el('div',undefined,'event-head');const branch=branchFor(e);head.append(el('span',branch==='main'?'music':branch,'branch-badge '+branch),el('span',e.period,'event-period'));li.append(head);const content=el('div',undefined,e.id==='parallel'?'overlap':'event-content');content.append(el('h3',e.title,'event-title'));if(e.id!=='birth'){const notes=el('details',undefined,'era-notes');notes.append(el('summary',e.id==='felice-end'?'活動の記録':'時代のノーツ'));if(e.description)notes.append(el('p',e.description));let populated=Boolean(e.description);for(const [key,label] of [['musicPlayed','やっていた音楽'],['musicListenedTo','聴いていた音楽'],['creativeMindset','曲を作るときの気持ち'],['reflectionNow','今、振り返って'],['reworkingNow','今、再制作して']]){if(e.eraNotes?.[key]){notes.append(el('h4',label),el('p',e.eraNotes[key]));populated=true;}}if(!populated)notes.append(el('p','この時代のノーツは、これから。','empty-note'));content.append(notes);}if(e.trackIds?.length){const commits=el('div',undefined,'commits '+branch);for(const id of e.trackIds){const t=tracks.find(x=>x.id===id);if(!t)continue;const b=el('button',undefined,'commit');b.setAttribute('aria-label',t.title+'の詳細を開く');b.append(el('span',String(tracks.indexOf(t)+1).padStart(2,'0'),'commit-index'),el('span',undefined,'commit-dot'),el('span',t.title,'commit-title'),el('span','↗','commit-arrow'));b.addEventListener('click',()=>openDetail(t));commits.append(b);}content.append(commits);}li.append(content);list.append(li);}requestAnimationFrame(drawGraph);}
function drawGraph(){const svg=$('#graph');svg.replaceChildren();const tree=$('#tree');const height=tree.offsetHeight;const width=svg.getBoundingClientRect().width;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const x={main:width*.18,felice:width*.51,patalp:width*.84};const rows=[...$('#history-list').children];const y=id=>{const r=rows.find(l=>l.dataset.event===id);return r?r.offsetTop+12:null;};const ns='http://www.w3.org/2000/svg';const path=(d,color,dash)=>{const p=document.createElementNS(ns,'path');p.setAttribute('d',d);p.setAttribute('stroke',color);p.setAttribute('stroke-width','2');p.setAttribute('fill','none');if(dash)p.setAttribute('stroke-dasharray','4 6');svg.append(p);};const mainColor='#9aae9c',feliceColor='#d6ae6c',patalpColor='#97a9e1';path(`M ${x.main} ${y('birth')} L ${x.main} ${y('engineer')}`,mainColor);const split=y('split'),firstF=y('felice'),firstP=y('patalp'),endF=y('felice-end'),parallel=y('parallel');if(split!==null&&firstF!==null){path(`M ${x.main} ${split} C ${x.main} ${split+30}, ${x.felice} ${split+30}, ${x.felice} ${firstF} L ${x.felice} ${endF}`,feliceColor);}if(split!==null&&firstP!==null){path(`M ${x.main} ${split} C ${x.main} ${split+45}, ${x.patalp} ${split+45}, ${x.patalp} ${firstF} L ${x.patalp} ${parallel}`,patalpColor);path(`M ${x.patalp} ${parallel} L ${x.patalp} ${endF+28}`,patalpColor,true);}for(const r of rows){const branch=r.dataset.branch;const yy=r.offsetTop+12;const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',String(x[branch]));dot.setAttribute('cy',String(yy));dot.setAttribute('r',r.dataset.event==='split'?'5':'4');dot.setAttribute('fill','#111816');dot.setAttribute('stroke',branch==='felice'?feliceColor:branch==='patalp'?patalpColor:mainColor);dot.setAttribute('stroke-width','2');svg.append(dot);}if(endF!==null){path(`M ${x.felice-5} ${endF+9} L ${x.felice+5} ${endF+9}`,feliceColor);}}
const observer=new ResizeObserver(()=>requestAnimationFrame(drawGraph));observer.observe($('#tree'));
window.addEventListener('resize',()=>requestAnimationFrame(drawGraph));
async function init(){try{const responses=await Promise.all([fetch('tracks.json'),fetch('history.json')]);if(responses.some(r=>!r.ok))throw Error('data');[tracks,events]=await Promise.all(responses.map(r=>r.json()));render();}catch{$('#error').hidden=false;$('#error').textContent='音楽の履歴を読み込めませんでした。ページを再読み込みしてください。';}}
init();
